{\em{\cite[Theorem 4.1.2]{Thomas-Tuneski}}} Let $f \in \mathcal{S}^*(\mathbb{U})$ and be given by \eqref{eq1}. Then
\begin{align*}
(n + 1)^2 \vert{}a_n\vert{}^2 \leqslant 4 \left( 1 + \sum_{k=2}^{n} k \vert{}a_k\vert{}^2 \right)
\end{align*}
for $n \geqslant 2$. Equality holds if and only if $f$ is a rotation of the Koebe function.

{\em{\cite[Theorem 4.2.4]{Thomas-Tuneski}}}
Let $f \in \mathcal{K}(\mathbb{U})$ be given by \eqref{eq1}. Then for $n \geqslant 2$,
\begin{align*}
n^2(n + 1)^2 \vert{}a_n\vert{}^2 \leqslant 4 \left( 1 + \sum_{k=2}^{n} k^3 \vert{}a_k\vert{}^2 \right).
\end{align*}
Equality holds for the convex function $f(z)=z(1 - z)^{-1}$.

Let $f \in \mathcal{S}^*(\mathbb{U})$ and be given by \eqref{eq1}. Then, $\vert{}\vert{}a_{n+1}\vert{} - \vert{}a_n\vert{}\vert{} \le 1$  for $n \ge 2$. For a fixed $n$, equality holds if and only if $f(z) = f_0(z)$, where
\begin{align*}
f_0(z) = \frac{z}{(1 - \gamma z)(1 - \zeta z)}
\end{align*}
for some $\gamma$ and $\zeta$ satisfying $\vert{}\gamma\vert{} = \vert{}\zeta\vert{} = 1$.

{\em{\cite{Su2}}} Let $f:\mathbb{B}\to  X$ be a locally biholomorphic mapping. Then $f$ is a starlike mapping on $\mathbb{B}$ if and only if
\begin{align}
\Re\left\lbrace l_z\left([Df(z)]^{-1}f(z)\right)\right\rbrace>0,\quad z\in\mathbb{B}\backslash\{0\},\quad l_z\in T(z).
\end{align}

\label{Th-21}Let $f\in\mathcal{H}(\mathbb{B},\mathbb{C})$ with $f(0)=1$ and $F(z)=zf(z)\in\mathcal{S}(\mathbb{B})$. If
 \begin{align*}	
 \sum\limits_{n=2}^{\infty}n\left|l_{z}\left(\frac{D^{n}F(0)(z^{n})}{n!||z||^n}\right)\right|\leq 1
\end{align*}	
 for $z\in\mathbb{B}\backslash\{0\}$ and $l_z\in T(z)$, then $F(z)=zf(z)\in\mathcal{S}^*(\mathbb{B})$.

\label{Th-22}Let $f\in\mathcal{H}(\mathbb{B},\mathbb{C})$ with $f(0)=1$ and $F(z)=zf(z)\in\mathcal{S}^*(\mathbb{B})$. 
 Then for $z\in\mathbb{B}\backslash\{0\}$ and $l_z\in T(z)$, we have
 \begin{align*}
 	\left|l_{z}\left(\frac{D^{k}F(0)(z^{k})}{k!||z||^k}\right)\right|\leq k
 \end{align*}
 and
 \begin{align}\label{Th-22t}
 (n+1)^2\left|l_{z}\left(\frac{D^{n}F(0)(z^{n})}{n!||z||^n}\right)\right|^2\leq4\left(1+\sum\limits_{k=2}^{n}k	\left|l_{z}\left(\frac{D^{k}F(0)(z^{k})}{k!||z||^k}\right)\right|^2\right).	
 \end{align}
 Equality holds for the function $F(z)=f(z)z$, where
 \begin{align*}
 	f(z)=\frac{1}{(1-l_u(z))^2},\quad z\in\mathbb{B}\setminus\{0\},\quad ||u||=1.
 \end{align*}

\label{Th-23}Let $f\in\mathcal{H}(\mathbb{B},\mathbb{C})$ with $f(0)=1$ and $F(z)=zf(z)\in\mathcal{S}^*(\mathbb{B})$. Then for $k\geq2$, we have
\begin{align}\label{Th-23t}
\displaystyle
&\left|\;\left|\frac{l_z\left(D^{k+1}F(0)\left(z^{k+1}\right)\right)}{(k+1)!||z||^{k+1}}\right|-\left|\frac{l_z\left(D^{k}F(0)\left(z^{k}\right)\right)}{k!||z||^{k}} \right|\;\right|\leq 1,\quad z\in\mathbb{B}\backslash\{0\},\quad l_z\in T(z).
\end{align}
Equality holds for the function $F$ defined as in Theorem \ref{Th-22}.

\label{Lem1} {\em{\cite{Cho-Kumar-Ravichandran-2019}}}
Let $p(z)=1+\sum_{n=1}^{\infty}p_nz^n\in\mathcal{P}$. Then
\begin{align*}
\displaystyle
|p_n|\leq 2\quad \text{and}\quad |p_n-p_mp_{n-m}|\leq 2,\quad n\geq 2,\;1\leq m\leq n-1.
\end{align*}

By the given condition, we have $f\in\mathcal{H}(\mathbb{B},\mathbb{C})$ with $f(0)=1$ and $F(z)=zf(z)\in\mathcal{S}(\mathbb{B})$. Let $z\in \mathbb{B}\backslash\{0\}$ be fixed. Suppose $z_0=z/\|z\|$. We define the function $g:\mathbb{U}\to \mathbb{C}$ as follows
\begin{align}\label{Th-21.0}	
	\displaystyle
	g(\zeta)=\begin{cases}
		\frac{\zeta}{l_{z_0}\left([D F(\zeta z_0)]^{-1}F(\zeta z_0)\right)},& \zeta\neq 0,\\[8pt]
		1& \zeta=0.
	\end{cases}
\end{align}
Using a similar method as in Theorem 7.1.14 \cite{Graham-Kohr}, we have
\begin{align}\label{Th-21.1}
	[D F(z)]^{-1}\eta=\frac{1}{f(z)}\left\lbrack \eta-\frac{\frac{(Df(z){\eta})z}{f(z)}}{1+\frac{Df(z)z}{f(z)}}\right\rbrack.
\end{align}
Therefore,
\begin{align}\label{Th-21.2}
	[D F(z)]^{-1}F(z)=\frac{zf(z)}{f(z)+D f(z)z},
\end{align}
which implies that
\begin{align}\label{Th-21.3}
g(\zeta)=\frac{\zeta}{l_{z_0}\left([D F(\zeta z_0)]^{-1}F(\zeta z_0)\right)}=1+\frac{Df(\zeta z_0) \zeta z_0}{f(\zeta z_0)}.
\end{align}
If
\begin{align}\label{Th-21.4}
f(z)=1+\sum\limits_{k=1}^{\infty} \frac{1}{k!}D^kf(0)(z^k),
\end{align}	
then it is clearly
\begin{align}\label{Th-21.5}
Df(z)(z)=\sum\limits_{k=1}^{\infty} \frac{k}{k!}D^kf(0)(z^k).
\end{align}	
Since $F(z)=zf(z)$, we have (see \cite[Theorem 2]{Xiong-Yu-Wang-2025})
\begin{align}\label{Th-21.6}
D^mF(0)(z^m)=mD^{m-1}f(0)(z^{m-1})z
\end{align}
where $m\in\mathbb{N}$. As $z_0=z/||z||$, we deduce from \eqref{Th-21.6} that
\begin{align}\label{Th-21.7}
\displaystyle
\frac{l_{z_0}(D^mF(0)(z_0^m))}{m!}=\frac{D^{m-1}f(0)(z_0^{m-1})}{(m-1)!}.
\end{align}
On the other hand, using \eqref{Th-21.7} to \eqref{Th-21.4} and \eqref{Th-21.5}, we find that
\begin{align}\label{Th-21.8}
f(\zeta z_0)=1+\sum\limits_{k=1}^{\infty} l_{z_0}\left(\frac{1}{(k+1)!}D^{k+1}F(0)(z_0^{k+1})\right)\zeta^k
\end{align}	
and
\begin{align}\label{Th-21.9}
Df(\zeta z_0)(\zeta z_0)=\sum\limits_{k=1}^{\infty} kl_{z_0}\left(\frac{1}{(k+1)!}D^{k+1}F(0)(z_0^{k+1})\right)\zeta^{k}.
\end{align}	
Now using \eqref{Th-21.8} and \eqref{Th-21.9}, we deduce that
\begin{align*}
&|g(\zeta)f(\zeta z_0)-f(\zeta z_0)|-|f(\zeta z_0)|\\=&|Df(\zeta z_0))(\zeta z_0)|-|f(\zeta z_0)|\nonumber\\=&
\left|\sum\limits_{k=1}^{\infty}kl_{z_0}\left(\frac{D^{k+1}F(0)(z_0^{k+1})}{(k+1)!}\right)\zeta^{k}\right|-\left|1+\sum\limits_{k=1}^{\infty}l_{z_0}\left(\frac{D^{k+1}F(0)(z_0^{k+1})}{(k+1)!}\right)\zeta^{k}\right|\nonumber\\<&
\sum\limits_{k=1}^{\infty}k\left|l_{z_0}\left(\frac{D^{k+1}F(0)(z_0^{k+1})}{(k+1)!}\right)\right|-\left(1-\sum\limits_{k=1}^{\infty}\left|l_{z_0}\left(\frac{D^{k+1}F(0)(z_0^{k+1})}{(k+1)!}\right)\right|\right)\nonumber\\=&
\sum\limits_{n=2}^{\infty}n\left|l_{z_0}\left(\frac{D^{n}F(0)(z_0^{n})}{n!}\right)\right|-1\leq 0\nonumber
\end{align*}
and so for $\zeta\in\mathbb{U}\backslash\{0\}\}$, we have $\left|g(\zeta)-1\right|<1.$ This shows that  $\Re\{g(\zeta)\}>0$ for all $\zeta\in\mathbb{U}\backslash\{0\}$, i.e.,
\begin{align}\label{Th-21.10}
\Re\left\lbrace \frac{\zeta}{l_{z_0}\left([D F(\zeta z_0)]^{-1}F(\zeta z_0)\right)}\right\rbrace>0
\end{align}
for all $\zeta\in\mathbb{U}\backslash\{0\}$. Substituting $\zeta=||z||$ into \eqref{Th-21.10} and using the fact that
$l_{\alpha z}=\frac{|\alpha|}{\alpha}l_z$
for each $\alpha\in\mathbb{U}\backslash\{0\}$, we obtain
\begin{align*}
\Re\left\lbrace \frac{||z||}{l_{z}\left([D F(z)]^{-1}F( z)\right)}\right\rbrace>0,\quad z\in\mathbb{B}\backslash\{0\}, \quad l_z\in T(z).
\end{align*}
Consequently $F\in \mathcal{S}^*(\mathbb{B})$.

By the given condition, $F\in\mathcal{S}^*(\mathbb{B})$. Then we have
\begin{align}\label{Th-22.0}
	\displaystyle
	\Re\left\lbrace \frac{\|z\|}{l_z\left([D F(z)]^{-1}F(z)\right)}\right\rbrace>0, \quad z\in\mathbb{B}\backslash \{0\},\quad l_z\in T(z).
\end{align}
Let $z\in \mathbb{B}\backslash\{0\}$ be fixed. Suppose $z_0=z/\|z\|$. Also, we consider the function $g:\mathbb{U}\to \mathbb{C}$ defined by \eqref{Th-21.0}.
Clearly $g\in\mathcal{H}(\mathbb{U})$ and $g(0)=1$.
 Therefore for $\zeta\in\mathbb{U}\backslash\{0\}$, we have
\begin{align}\label{Th-22.1}
	\displaystyle
	g(\zeta)=\frac{\zeta}{l_{z_0}\left([D F(\zeta z_0)]^{-1}F(\zeta z_0)\right)}=\frac{\|\zeta z_0\|}{l_{\zeta z_0}\left([D F(\zeta z_0)]^{-1}F(\zeta z_0)\right)}.
\end{align}	
Consequently $\Re\{g(\zeta)\}>0$ for all $\zeta\in\mathbb{U}$. Suppose
\begin{align}\label{Th-22.2}
g(\zeta)=1+\sum_{k=1}^{\infty}g_k\zeta^k.
\end{align}
                                                                              

Using \eqref{Th-21.8}, \eqref{Th-21.9} and \eqref{Th-22.2} to \eqref{Th-21.3}, we get
\begin{align}\label{Th-22.3}
&\left(1+\sum_{k=1}^{\infty}g_k\zeta^k\right)\left(1+\sum\limits_{k=1}^{\infty}l_{z_0}\left(\frac{1}{(k+1)!}D^{k+1}F(0)(z_0^{k+1})\right)
\zeta^{k}\right)\\=&
1+\sum\limits_{k=1}^{\infty} (k+1)l_{z_0}\left(\frac{1}{(k+1)!}D^{k+1}F(0)(z_0^{k+1})\right)\zeta^{k}.\nonumber	
\end{align}
By equating coefficients on the both sides of \eqref{Th-22.3}, we get
\begin{align}\label{Th-22.4}
(k+1)l_{z_0}\left(\frac{1}{(k+1)!}D^{k+1}F(0)(z_0^{k+1})\right)=&l_{z_0}\left(\frac{1}{(k+1)!}D^{k+1}F(0)(z_0^{k+1})\right)\\+&\sum\limits_{i=1}^{k-1}g_{k-i}\;l_{z_0}\left(\frac{1}{(i+1)!}D^{i+1}F(0)(z_0^{i+1})\right)+g_{k}.\nonumber
\end{align}
We now use mathematical induction and suppose
\begin{align*}
\left|l_{z_0}\left(\frac{1}{i!}D^{i}F(0)(z_0^{i})\right)\right|\leq i\quad \text{for}\;\;i=2,3,\ldots,k.
\end{align*}
Applying Lemma \ref{Lem1} to \eqref{Th-22.4}, we get
\begin{align*}
k\left|l_{z_0}\left(\frac{1}{(k+1)!}D^{k+1}F(0)(z_0^{k+1})\right)\right|\leq 2\sum\limits_{i=1}^{k-1}(i+1)+2=k(k+1),
\end{align*}
which shows that
\begin{align*}
\left|l_{z_0}\left(\frac{1}{(k+1)!}D^{k+1}F(0)(z_0^{k+1})\right)\right|\leq k+1.
\end{align*}
Then by induction, we have
\begin{align*}
\left|l_{z_0}\left(\frac{1}{k!}D^{k}F(0)(z_0^{k})\right)\right|\leq k.
\end{align*}
\par This proves the first inequality.
\par Since $\Re\{g(\zeta)\}>0$ for all $\zeta\in\mathbb{U}$, there exists a Schwarz function $\omega(\zeta)$ with $\omega(\zeta)=\sum_{k=1}^{\infty}\omega_k\zeta^k$ such that $g(\zeta)=(1+\omega(\zeta))/(1-\omega(\zeta))$ and so from \eqref{Th-21.3}, we get
\begin{align}\label{Th-22.5}
\left(2f(\zeta z_0)+Df(\zeta z_0) \zeta z_0\right)\omega(\zeta)=Df(\zeta z_0) \zeta z_0.
\end{align}
Using \eqref{Th-21.8} and \eqref{Th-21.9} to \eqref{Th-22.5}, we obtain
\begin{align}\label{Th-22.6}
\left(2+\sum\limits_{k=1}^{\infty}(k+2)a_{k+1} \zeta^k \right)\omega(\zeta)=\sum\limits_{k=1}^{\infty}ka_{k+1}\zeta^k,
\end{align}
where
\begin{align}\label{Th-22.7}
a_{k+1}=l_{z_0}\left(\frac{1}{(k+1)!}D^{k+1}F(0)(z_0^{k+1})\right)
\end{align}
Equating coefficients on the both sides of \eqref{Th-22.6}, one can easily get
\begin{align*}
2\omega_k+3a_2\omega_{k-1}+\ldots+(k+1)a_k\omega_1=ka_{k+1}.
\end{align*}
This shows that the coefficient $a_{k+1}$ depends only on $a_2$, $a_3\ldots$,$a_k$. Therefore we can rewrite \eqref{Th-22.6} as follows
\begin{align}\label{Th-22.8}
	\left(2+\sum\limits_{k=1}^{n-1}(k+2)a_{k+1} \zeta^k \right)\omega(\zeta)=\sum\limits_{k=1}^{n}ka_{k+1}\zeta^k+\sum\limits_{k=n+1}^{\infty}b_k\zeta^k
\end{align}
for some $b_k$.
Let $\zeta=re^{i\theta}$. Then from \eqref{Th-22.8}, we get
\begin{align}\label{Th-22.9}
\left(2+\sum\limits_{k=1}^{n-1}(k+2)a_{k+1} r^ke^{ik\theta} \right)\omega(re^{i\theta})=\sum\limits_{k=1}^{n}ka_{k+1}r^ke^{ik\theta}+\sum\limits_{k=n+1}^{\infty}b_kr^ke^{ik\theta}
\end{align}
and
\begin{align}\label{Th-22.10}
\left(2+\sum\limits_{k=1}^{n-1}(k+2)\overline a_{k+1} r^ke^{-ik\theta} \right)\omega(re^{-i\theta})=\sum\limits_{k=1}^{n}k\overline a_{k+1}r^ke^{-ik\theta}+\sum\limits_{k=n+1}^{\infty}\overline b_kr^ke^{-ik\theta}.
\end{align}
Note that $|\omega(\zeta)|<1$ for all $\zeta\in\mathbb{U}$. We first multiply \eqref{Th-22.9} and \eqref{Th-22.10} and then integrating with respect to $\theta$ from $0$ to $2\pi$, we can find that
\begin{align*}
\sum\limits_{k=1}^{n}k^2|a_{k+1}|^2r^{2k}+\sum\limits_{k=n+1}^{\infty}|b_k|^2r^{2k}<4+\sum\limits_{k=1}^{n-1}(k+2)^2|a_{k+1}|^2r^{2k}.
\end{align*}
Letting $r\to 1$, we obtain
\begin{align*}
\sum\limits_{k=1}^{n}k^2|a_{k+1}|^2\leq 4+\sum\limits_{k=1}^{n-1}(k+2)^2|a_{k+1}|^2,
\end{align*}
i.e.,
\begin{align*}
n^2|a_{n+1}|^2\leq 4\left(1+\sum\limits_{k=1}^{n-1}(k+1)|a_{k+1}|^2\right)=4\left(1+\sum\limits_{i=2}^{n}i|a_{i}|^2\right),
\end{align*}
or
\begin{align*}
(m-1)^2|a_{m}|^2\leq 4\left(1+\sum\limits_{i=2}^{m-1}i|a_{i}|^2\right).
\end{align*}
Now adding $4m|a_{m}|^2$ on the both sides and then using \eqref{Th-22.7}, we get the required conclusion \eqref{Th-22t}.\vspace{1.9mm}

{\bf Sharpness part:} Let us consider $F(z)=f(z)z$, where
\begin{align*}
f(z)=\frac{1}{(1-l_u(z))^2},\quad z\in\mathbb{B},\quad ||u||=1.
\end{align*}

According to Lemma 2.2 \cite{Xu-He-Xu}, it is clear that $F\in\mathcal{S}^*(\mathbb{B})$. Note that $F(z)=\sum_{n=0}^{\infty}(n+1)(l_u(z))^{n}\;z$, $z\in\mathbb{B}$.
A straightforward computation shows that
\begin{align}\label{Th-22.11}
\frac{D^{k+1}F(0)\left(z^{k+1}\right)}{(k+1)!}=(k+1)(l_u(z))^k z\quad \text{and}\quad \frac{D^{k}F(0)\left(z^{k}\right)}{k!}=k(l_u(z))^{k-1} z.
\end{align}
Taking $z=ru\;(0<r<1)$, we get
\begin{align*}
\frac{l_z\left(D^{k+1}F(0)\left(z^{k+1}\right)\right)}{(k+1)!||z||^{k+1}}=k+1,\quad \frac{D^{k}F(0)\left(z^{k}\right)}{k!||z||^k}=k
\end{align*}
and so equality of \eqref{Th-22t} holds.

By the given condition, $F\in\mathcal{S}^*(\mathbb{B})$. Let $z\in \mathbb{B}\backslash\{0\}$ be fixed. Suppose $z_0=z/\|z\|$. We consider the function $g:\mathbb{U}\to \mathbb{C}$ defined by \eqref{Th-21.0}. Clearly
$g\in\mathcal{H}(\mathbb{U})$ with $g(0)=1$ and $\Re\{g(\zeta)\}>0$ for all $\zeta\in\mathbb{U}$.
Let
\begin{align}\label{Th-23.1}
\displaystyle
h(\zeta)=f(\zeta z_0)=1+D f(0)(z_0)\zeta+\frac{1}{2!}D^2 f(0)(z_0^2)\zeta^2+\ldots.
\end{align}
Clearly
\begin{align}\label{Th-23.2}
\displaystyle
D f(\zeta z_0)(\zeta z_0)=D f(0)(z_0)\zeta+D^2 f(0)(z_0^2)\zeta^2+\ldots
\end{align}
From \eqref{Th-23.1} and \eqref{Th-23.2}, we have $h'(\zeta)\zeta=D f(\zeta z_0)(\zeta z_0)$. Now from \eqref{Th-21.3}, we get
\begin{align*}
	g(\zeta)=1+\frac{\zeta h'(\zeta)}{h(\zeta)}.
\end{align*}
Now from \eqref{Th-22.2}, we have
\begin{align*}
h'(\zeta)/h(\zeta)=\sum_{k=1}^{\infty}g_k\zeta^{k-1}.
\end{align*}
Integration gives
\begin{align*}
	\displaystyle
	\log h(\zeta)=\sum\limits_{k=1}^{\infty}\frac{1}{k}g_k\zeta^k.
\end{align*}
Also for $\xi \in\partial \mathbb{U}$, we have
\begin{align}\label{Th-23.3}
	\log \left\lbrace (1-\xi \zeta)h(\zeta)\right\rbrace=\sum\limits_{k=1}^{\infty}\alpha_k\zeta^k,
\end{align}
where
\begin{align}\label{Th-23.4}
	\alpha_k=\frac{1}{k}(g_k-\xi^k).
\end{align}
On the other hand, from \eqref{Th-23.1}, we get
\begin{align}\label{Th-23.5}
(1-\xi \zeta)h(\zeta)=\sum\limits_{k=0}^{\infty}\beta_k\zeta^k,
\end{align}
where
\begin{align}\label{Th-23.6}
	\begin{cases}
		\beta_0=&1,\\[8pt]
		\beta_1=&Df(0)(z_0)-\xi,\\[8pt] \beta_k=&\frac{1}{(k+1)!}D^{k+1}f(0)\left(z_0^{k+1}\right)-\xi\frac{1}{k!} D^kf(0)\left(z_0^k\right)\quad \text{for} \;\;k\geq 2.
	\end{cases}
\end{align}
Now from \eqref{Th-23.3} and \eqref{Th-23.5}, we obtain
\begin{align*}
	\sum\limits_{k=0}^{\infty}\beta_k \zeta^k=\exp\left\lbrace \sum\limits_{k=1}^{\infty} \alpha_k \zeta^k\right\rbrace.
\end{align*}
Applying Third Lebedev-Milin inequality (see \cite[pp.143]{Duren-1983}), we get
\begin{align*}
	|\beta_k|^2\leq \exp\left\lbrace \sum\limits_{n=1}^{k}n|\alpha_n|^2-\sum\limits_{n=1}^k\frac{1}{n}\right\rbrace
\end{align*}
and so from \eqref{Th-23.6}, we have
\begin{align}\label{Th-23.7}
\left|\frac{D^{k+1}f(0)\left(z_0^{k+1}\right)}{(k+1)!}-\xi\frac{D^kf(0)\left(z_0^k\right)}{k!} \right|\leq \exp\left\lbrace \sum\limits_{n=1}^{k}\frac{1}{n}|g_n-\xi^n|^2-\sum\limits_{n=1}^k\frac{1}{n}\right\rbrace.
\end{align}

By Corollary \cite[pp.178]{Duren-1983}, we can choose $\xi\in\partial \mathbb{U}$ so as to make the exponent in \eqref{Th-23.7} nonpositive, to obatin
\begin{align*}
	\left|\frac{1}{(k+1)!}D^{k+1}f(0)\left(z_0^{k+1}\right)-\xi\frac{1}{k!} D^kf(0)\left(z_0^k\right)\right|\leq 1.
\end{align*}
Therefore,
\begin{align}\label{Th-23.8}
	\displaystyle
	&\left|\;\left|\frac{1}{(k+1)!}D^{k+1}f(0)\left(z_0^{k+1}\right)\right|-\left|\frac{1}{k!} D^kf(0)\left(z_0^k\right)\right|\;\right|\\\leq& 	\left|\frac{1}{k+1}D^{(k+1)!}f(0)\left(z_0^{k+1}\right)-\xi\frac{1}{k!} D^kf(0)\left(z_0^k\right)\right|\leq 1\nonumber
\end{align}
for all $\xi\in\partial \mathbb{U}$.
Since $z_0=z/\|z\|$, using \eqref{Th-21.7}, we deduce from \eqref{Th-23.8} that
\begin{align*}
	\displaystyle
	&\left|\;\left|\frac{l_z\left(D^{k+2}F(0)\left(z^{k+2}\right)\right)}{(k+2)!||z||^{k+2}}\right|-\left|\frac{l_z\left(D^{k+1}F(0)\left(z^{k+1}\right)\right)}{(k+1)!||z||^{k+1}} \right|\;\right|\leq 1,\quad z\in\mathbb{B}\backslash\{0\}\nonumber
\end{align*}
for $k\geq 1$.\vspace{2mm}

To establish the sharpness of the bound, let us consider the function $F$ defined as in Theorem \ref{Th-22}.
Putting $z=ru\;(0<r<1)$ into \eqref{Th-22.11}, we get
\begin{align*}
\frac{l_z\left(D^{k+1}F(0)\left(z^{k+1}\right)\right)}{(k+1)!||z||^{k+1}}=k+1,\quad \frac{D^{k}F(0)\left(z^{k}\right)}{k!||z||^k}=k
\end{align*}
and so equality of \eqref{Th-23t} holds.

\label{Th-31}Let $f\in\mathcal{H}(\mathbb{B},\mathbb{C})$ with $f(0)=1$ and $F(z)=zf(z)\in\mathcal{S}(\mathbb{B})$. If
\begin{align*}	
\sum\limits_{n=2}^{\infty}n^2\left|l_{z}\left(\frac{D^{n}F(0)(z^{n})}{n!||z||^n}\right)\right|\leq 1
\end{align*}	
for $z\in\mathbb{B}\backslash\{0\}$ and $l_z\in T(z)$, then $F(z)=zf(z)\in\mathcal{K}_B(\mathbb{B})$.

\label{Th-32}Let $f\in\mathcal{H}(\mathbb{B},\mathbb{C})$ with $f(0)=1$ and $F(z)=zf(z)\in\mathcal{K}_B(\mathbb{B})$. Then for for $z\in\mathbb{B}\backslash\{0\}$ and $l_z\in T(z)$, we have
\begin{align*}
