for $k=2,3$.

By the given condition, we have $f\in\mathcal{H}(\mathbb{B},\mathbb{C})$ with $f(0)=1$ and $F(z)=zf(z)\in\mathcal{S}(\mathbb{B})$.	
Let $z\in \mathbb{B}\backslash\{0\}$ be fixed and let $z_0=z/\|z\|$. We define the function $g:\mathbb{U}\to \mathbb{C}$ as follows
\begin{align}\label{Th-31.0}	
\displaystyle
g(\zeta)=\begin{cases}
\frac{l_{z}\left([DF(\zeta z_0)]^{-1}\left(D^2 F(\zeta z_0)(\zeta^2z_0^2)+DF(\zeta z_0) \zeta z_0\right)\right)}{\zeta},& \zeta\neq 0,\\[8pt]
1,& \zeta=0.
\end{cases}
\end{align}
Let $\phi(z)=D^2 F(z)(z^2)+DF(z)z$.		
Since $F(z)$ is normalized, it has the power series expansion
\begin{align}\label{Th-31.2}
\displaystyle
F(z)=z+\sum\limits_{k=2}^{\infty}\frac{1}{k!}D^k F(0)(z^k).
\end{align}
Clearly
\begin{align}\label{Th-31.3}
\displaystyle
D F(z)=I+\sum\limits_{k=2}^{\infty}\frac{k}{k!}D^k F(0)(z^{k-1})
\end{align}
and
\begin{align}\label{Th-31.4}
\displaystyle
D^2 F(z)=\sum\limits_{k=2}^{\infty}\frac{k(k-1)}{k!}D^k F(0)(z^{k-2})
\end{align}
Using \eqref{Th-31.3} and \eqref{Th-31.4}, we get
\begin{align*}
\phi(z)=z+\sum\limits_{k=2}^{\infty}\frac{k^2}{k!}D^k F(0)(z^{k})
\end{align*}
and so
\begin{align}\label{Th-31.5}
l_{z_0}(\phi(\zeta z_0))=\zeta+\sum\limits_{k=2}^{\infty}k^2a_k\zeta^k,
\end{align}	
where
\begin{align}\label{Th-31.5a}
a_k=l_{z_0}\left(\frac{1}{k!}D^3F(0)(z_0^3)\right).
\end{align}	
On the other hand, from \eqref{Th-21.8} and \eqref{Th-21.9}, we obtain
\begin{align}\label{Th-31.6}
\psi(\zeta)=f(\zeta z_0)+D f(\zeta z_0)\zeta z_0=1+\sum\limits_{k=1}^{\infty}(k+1)a_{k+1}\zeta^k=1+\sum\limits_{k=2}^{\infty}ka_{k}\zeta^{k-1}
\end{align}
Again \eqref{Th-21.1} gives
\begin{align}\label{Th-31.7}
\displaystyle
[D F(z)]^{-1}\phi(z)=\frac{\phi(z)}{f(z)+D f(z)z}.
\end{align}	
In view of \eqref{Th-31.0} and using \eqref{Th-31.5}, \eqref{Th-31.6} to \eqref{Th-31.7}, we obtain
\begin{align}\label{Th-31.8}
\displaystyle
g(\zeta)=\frac{1+\sum\limits_{k=2}^{\infty}k^2a_k\zeta^{k-1}}{1+\sum\limits_{k=2}^{\infty}ka_{k}\zeta^{k-1}}.	
\end{align}
Now applying \eqref{Th-31.6} and \eqref{Th-31.8}, we have
\begin{align*}
\left|g(\zeta)\psi(\zeta)-\psi(\zeta)\right|-|\psi(\zeta)|=&\left|\sum\limits_{k=2}^{\infty}(k^2-k)a_k\zeta^{k-1}\right|-\left|1+\sum\limits_{k=2}^{\infty}ka_{k}\zeta^{k-1}\right|\\<&
\sum\limits_{k=2}^{\infty}(k^2-k)|a_k|-\left(1-\sum\limits_{k=2}^{\infty}k|a_{k}|\right)=
\sum\limits_{k=2}^{\infty}k^2|a_k|-1\leq 0
\end{align*}
and so for $\zeta\in\mathbb{U}\backslash\{0\}\}$, we have $\left|g(\zeta)-1\right|<1.$ This shows that $g(\zeta)$ lies inside a circle with center at $(1,0)$ and radius $1$ and so $\Re\{g(\zeta)\}>0$ for all $\zeta\in\mathbb{U}\backslash\{0\}$, i.e.,
\begin{align}\label{Th-31.9}
\Re\left\lbrace \frac{l_{z_0}\left([D F(\zeta z_0)]^{-1}\phi(\zeta z_0)\right)}{\zeta}\right\rbrace>0
\end{align}
for all $\zeta\in\mathbb{U}\backslash\{0\}$. Substituting $\zeta=||z||$ into \eqref{Th-31.9} and using the fact that
$l_{\alpha z}=\frac{|\alpha|}{\alpha}l_z$
for each $\alpha\in\mathbb{U}\backslash\{0\}$, we obtain
\begin{align*}
	\Re\left\lbrace \frac{l_{z}\left([D F(z)]^{-1}\left(D^2 F(z)(z^2)+DF(z) z\right)\right)}{||z||}\right\rbrace>0,\quad z\in\mathbb{B}\backslash\{0\}, \quad l_z\in T(z).
\end{align*}

Consequently \eqref{C1} yields $F\in \mathcal{K}_B(\mathbb{B})$.

By the given condition, we have $F\in\mathcal{K}_B(\mathbb{B})$ and so using \eqref{C1}, we must have
